const BURNDOWN = [140, 118, 125, 101, 80];
function forecastEnd(remaining) {
  var n = remaining.length - 1;
  if (n < 1) return Infinity;
  var burn = (remaining[0] - remaining[n]) / n;
  if (burn <= 0) return Infinity;
  return Math.ceil(remaining[n] / burn);
}
const SCOPE_GREW = BURNDOWN.some(function (v, i) { return i > 0 && v > BURNDOWN[i - 1]; });
